const parseServices = (body: unknown): OpsOAuthServiceSummary[] => {
  const services = (body as { services?: OpsOAuthServiceSummary[] } | null)?.services;
  if (!Array.isArray(services)) return [];
  return services;
};

function OpsIntegrationsTable({
  rows,
  loading,
}: {
  rows: OpsOAuthServiceSummary[];
  loading: boolean;
}) {
  const navigate = useNavigate();

  const openService = useCallback(
    (service: string) => {
      void navigate({ to: "/ops/integration/$service", params: { service } });
    },
    [navigate],
  );

  const columns = useMemo<ColumnDef<OpsOAuthServiceSummary>[]>(
    () => [
      {
        id: "provider",
        accessorFn: (row) => row.name || row.service,
        header: ({ column }) => <DataTableColumnHeader column={column} title="Provider" />,
        cell: ({ row }) => (
          <div className="flex min-w-0 items-center gap-2.5 py-0.5">
            {row.original.logo ? (
              <img
                src={row.original.logo}
                alt=""
                className="size-6 shrink-0 rounded border border-border bg-background object-contain p-0.5"
              />
            ) : (
              <span className="flex size-6 shrink-0 items-center justify-center rounded border border-border text-muted-foreground">
                <PlugZap className="size-3.5" />
              </span>
            )}
            <div className="min-w-0">
              <div className="truncate font-medium text-foreground">{row.original.name}</div>
              <div className="truncate font-mono text-xs text-muted-foreground">
                {row.original.service}
              </div>
            </div>
          </div>
        ),
        size: 240,
        minSize: 160,
        enableResizing: true,
        enableHiding: false,
      },
      {
        id: "service",
        accessorKey: "service",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Slug" />,
        cell: ({ row }) => (
          <span className="font-mono text-xs text-muted-foreground">{row.original.service}</span>
        ),
        size: 140,
        enableResizing: true,
      },
      {
        id: "category",
        accessorKey: "category",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Category" />,
        cell: ({ row }) => (
          <Badge variant="metadata" tone="muted" className="font-normal">
            {row.original.category}
          </Badge>
        ),
        size: 150,
        enableResizing: true,
      },
      {
        id: "connections",
        accessorFn: (row) =>
          row.connections.map((c) => `${c.credentialStrategy} ${c.lifecycleStatus}`).join(" "),
        header: "Connections",
        cell: ({ row }) => (
          <div className="flex flex-wrap gap-1">
            {row.original.connections.length === 0 ? (
              <span className="text-muted-foreground">—</span>
            ) : (
              row.original.connections.map((connection) => (
                <LifecycleBadge
                  key={connection.credentialStrategy}
                  lifecycle={connection.lifecycleStatus}
                  strategy={connection.credentialStrategy}
                />
              ))
            )}
          </div>
        ),
        size: 260,
        minSize: 180,
        enableSorting: false,
        enableResizing: true,
      },
      {
        id: "allowlist",
        accessorFn: (row) =>
          row.connections.reduce((sum, connection) => sum + connection.experimentalOrgCount, 0),
        header: ({ column }) => <DataTableColumnHeader column={column} title="Experimental orgs" />,
        cell: ({ row }) => {
          const count = row.original.connections.reduce(
            (sum, connection) => sum + connection.experimentalOrgCount,
            0,
          );
          return (
            <span className={count ? "tabular-nums" : "tabular-nums text-muted-foreground"}>
              {count}
            </span>
          );
        },
        size: 150,
        enableResizing: true,
      },
      {
        id: "secret",
        accessorFn: (row) =>
          row.connections.some((connection) => connection.clientSecretConfigured) ? 1 : 0,
        header: ({ column }) => <DataTableColumnHeader column={column} title="Secret" />,
        cell: ({ row }) => {
          if (row.original.connections.length === 0) {
            return <span className="text-muted-foreground">—</span>;
          }
          const configured = row.original.connections.every(
            (connection) => connection.clientSecretConfigured,
          );
          const partial = row.original.connections.some(
            (connection) => connection.clientSecretConfigured,
          );
          return (
            <Badge
              variant="metadata"
              tone={configured ? "success" : partial ? "warning" : "muted"}
              className="font-normal"
            >
              {configured ? "configured" : partial ? "partial" : "missing"}
            </Badge>
          );
        },
        size: 130,
        enableResizing: true,
      },
    ],
    [],
  );

  const { table, search, setSearch } = useOpsDataTable({
    data: rows,
    columns,
    getRowId: (row) => row.service,
    defaultSorting: [{ id: "provider", desc: false }],
    defaultColumnVisibility: { service: false },
    searchHaystack: (row) => [
      row.service,
      row.name,
      row.description,
      row.category,
      ...row.connections.map(
        (connection) =>
