/**
 * Settings → Connectors catalog model (product surface).
 */

export type ConnectorSource = "genesis" | "mcp" | "both";

export type ConnectorStatus = "installed" | "available" | "needs_attention" | "error";

export type ConnectorCategoryId =
  | "productivity"
  | "engineering"
  | "sales"
  | "finance"
  | "marketing"
  | "communication"
  | "other";

export type ConnectorBadge = "Sync" | "OAuth" | "API key" | "MCP";

export type ConnectorKind = "native" | "user_mcp" | "catalog_mcp";

export type ConnectorRecord = {
  id: string;
  name: string;
  description: string;
  iconUrl: string | null;
  category: ConnectorCategoryId;
  source: ConnectorSource;
  status: ConnectorStatus;
  badges: ConnectorBadge[];
  installedDetail: string | null;
  kind: ConnectorKind;
  /** Native broker integration id when kind is native (or both-de-duped as native). */
  integrationId: string | null;
  /** User MCP server row id when kind is user_mcp. */
  userMcpServerId: string | null;
  /** integrations.sh domain when kind is catalog_mcp. */
  catalogDomain: string | null;
  /** Native connected display name / account label. */
  connectedDisplayName: string | null;
  syncCapable: boolean;
  /**
   * Sort key for Browse: higher first.
   * integrations.sh popularity for catalog MCP; high constant for Genesis natives.
   */
  popularity: number;
};

export type ConnectorsSurfaceId = "catalog" | "secrets" | "genesis" | "activity";

/** Installed / saved user MCP server row (catalog merge + table actions). */
export type UserMcpServerListItem = {
  id: string;
  slug: string;
  displayName: string;
  url: string;
  description: string | null;
  iconUrl: string | null;
  status: string;
  lastErrorCode: string | null;
  authKind: string;
  headerName: string | null;
  headerTemplate: string | null;
  /** Cached tool names from discover/probe (display only). */
  lastTools: string[];
  lastProbeAt: string | null;
};

/** Public MCP catalog hit (integrations.sh) after API map. */
export type McpCatalogListHit = {
  id: string;
  slug: string;
  domain: string;
  name: string;
  description: string;
  icon: string | null;
  popularity?: number;
  categories?: string[];
};

