import { catalogDomainHintFromMcpUrl, looksLikeMcpHostLabel } from "@lib/user-mcp-display";
import { coverMcpCatalogHit } from "@lib/user-mcp-native-overlap";
import type { SettingsIntegration } from "@web/hooks/settings/use-settings-integrations";
import { isApiKeyIntegrationId } from "../../../../domain/api-key-integrations";
import { applyCatalogHitDisplayPatch } from "../../../../services/user-mcp-catalog-patches";
import { categoryForNativeIntegrationId, mapIntegrationsShCategory } from "./categories";
import type {
  ConnectorBadge,
  ConnectorRecord,
  ConnectorStatus,
  McpCatalogListHit,
  UserMcpServerListItem,
} from "./types";

export type { McpCatalogListHit, UserMcpServerListItem };

function resolveUserMcpDisplay(
  server: UserMcpServerListItem,
  catalogHits: readonly McpCatalogListHit[],
): { name: string; description: string; catalogDomain: string | null } {
  const domain = catalogDomainHintFromMcpUrl(server.url);
  const hit =
    domain != null
      ? catalogHits.find(
          (h) =>
            h.domain === domain || h.domain === `mcp.${domain}` || server.url.includes(h.domain),
        )
      : undefined;

  let name = server.displayName.trim();
  if (!name || looksLikeMcpHostLabel(name)) {
    if (hit?.name?.trim() && !looksLikeMcpHostLabel(hit.name)) {
      name = hit.name.trim();
    } else if (domain) {
      name = applyCatalogHitDisplayPatch({ domain, name: domain }).name;
    } else {
      name = server.displayName.trim() || "MCP server";
    }
  }

  const description =
    server.description?.trim() ||
    hit?.description?.trim() ||
    (statusInstalled(server.status) ? "Connected" : server.url);

  return { name, description, catalogDomain: hit?.domain ?? domain };
}

function statusInstalled(status: string): boolean {
  return status === "active";
}

function isNativeApiKeyIntegration(integrationId: string): boolean {
  // Keep client-safe (no integration-request-interaction / server imports).
  return isApiKeyIntegrationId(integrationId) || integrationId.trim().toLowerCase() === "printavo";
}

function nativeBadges(row: SettingsIntegration): ConnectorBadge[] {
  const badges: ConnectorBadge[] = [];
  if (isNativeApiKeyIntegration(row.id)) {
    badges.push("API key");
  } else {
    badges.push("OAuth");
  }
  if (row.syncCapable) badges.push("Sync");
  return badges;
}

function userMcpStatus(status: string): ConnectorStatus {
  if (status === "active") return "installed";
  if (status === "needs_reauth") return "needs_attention";
  if (status === "error") return "error";
  if (status === "disabled") return "available";
  return "available";
}

function userMcpBadges(authKind: string): ConnectorBadge[] {
  const badges: ConnectorBadge[] = ["MCP"];
  if (authKind === "oauth") badges.push("OAuth");
  if (authKind === "secret_header") badges.push("API key");
  return badges;
}

function userMcpAttentionDetail(server: UserMcpServerListItem): string {
  if (server.authKind === "secret_header") return "Access key required";
  if (
    server.authKind === "none" &&
    (server.lastErrorCode === "unauthorized" || server.lastErrorCode === "forbidden")
  ) {
    return "Access key required";
  }
  if (server.authKind === "oauth") return "Sign in required";
  return "Connection needs attention";
}

function markNativeBoth(native: ConnectorRecord): void {
  native.source = "both";
  if (!native.badges.includes("MCP")) {
    native.badges = [...native.badges, "MCP"];
  }
}

function catalogAlreadyInstalled(
  hit: McpCatalogListHit,
  userMcpServers: readonly UserMcpServerListItem[],
): boolean {
  return userMcpServers.some(
    (s) =>
      s.slug === hit.slug ||
      s.displayName.toLowerCase() === hit.name.toLowerCase() ||
      s.url.includes(hit.domain),
  );
}

/**
 * Build de-duped connectors for the marketplace.
 * Native wins when a catalog MCP maps to the same product.
 * Installed user MCP servers always appear (even if slug overlaps — reserved slugs are already _mcp).
 */
export function buildConnectorsCatalog(input: {
  integrations: readonly SettingsIntegration[];
  userMcpServers: readonly UserMcpServerListItem[];
  catalogHits: readonly McpCatalogListHit[];
}): ConnectorRecord[] {
  const { integrations, userMcpServers, catalogHits } = input;
  const byId = new Map<string, ConnectorRecord>();

  const nativeForOverlap = integrations.map((row) => ({
    id: row.id,
    name: row.name,
    connected: row.connected,
    syncCapable: row.syncCapable === true,
  }));

  // 1) Native broker integrations always present.
  for (const row of integrations) {
    const status: ConnectorStatus = row.connected
      ? row.googleAccess?.needsAccessUpdate
        ? "needs_attention"
        : "installed"
      : "available";
    byId.set(`native:${row.id}`, {
      id: `native:${row.id}`,
      name: row.name,
      description: row.description?.trim() || `Connect ${row.name} for this workspace.`,
      iconUrl: row.logo ?? null,
      category: categoryForNativeIntegrationId(row.id),
      source: "genesis",
      status,
      badges: nativeBadges(row),
      installedDetail: row.connected
        ? row.displayName?.trim()
          ? `Connected as ${row.displayName}`
          : row.googleAccess?.needsAccessUpdate
            ? "Reconnect required"
            : "Connected"
        : null,
      kind: "native",
      integrationId: row.id,
      userMcpServerId: null,
      catalogDomain: null,
      connectedDisplayName: row.displayName,
      syncCapable: row.syncCapable === true,
      // Prefer Genesis-built-in over remote MCP when filling Browse preview slots.
      popularity: 1_000_000,
    });
  }

  // 2) Installed / saved user MCP servers.
  for (const server of userMcpServers) {
    const status = userMcpStatus(server.status);
    const display = resolveUserMcpDisplay(server, catalogHits);
    byId.set(`user-mcp:${server.id}`, {
      id: `user-mcp:${server.id}`,
      name: display.name,
      description: display.description,
      iconUrl: server.iconUrl,
      category: "other",
      source: "mcp",
      status,
      badges: userMcpBadges(server.authKind),
      // Status column: short state only. Product blurb + tools live in Details.
      installedDetail:
        status === "error"
          ? server.lastErrorCode
            ? `Error · ${server.lastErrorCode}`
            : "Connection error"
          : status === "needs_attention"
            ? userMcpAttentionDetail(server)
            : status === "installed"
              ? "Connected"
              : null,
      kind: "user_mcp",
      integrationId: null,
      userMcpServerId: server.id,
      catalogDomain: display.catalogDomain,
      connectedDisplayName: null,
      syncCapable: false,
      popularity: 0,
    });
  }

  // 3) Public catalog MCP — one coverage decision per hit (native | product | unique).
  // Prefer higher popularity when several aliases share a product key.
  const emittedCatalogProductKeys = new Set<string>();
  const catalogHitsRanked = [...catalogHits].sort((a, b) => {
    const pa = typeof a.popularity === "number" ? a.popularity : 0;
    const pb = typeof b.popularity === "number" ? b.popularity : 0;
    if (pb !== pa) return pb - pa;
    return a.name.localeCompare(b.name);
  });

  for (const hit of catalogHitsRanked) {
    const coverage = coverMcpCatalogHit(
      { domain: hit.domain, name: hit.name, slug: hit.slug },
      nativeForOverlap,
    );

    if (coverage.kind === "native") {
      const native = byId.get(`native:${coverage.integrationId}`);
      if (native) markNativeBoth(native);
      continue;
    }

    if (coverage.kind === "product") {
      const native = byId.get(`native:${coverage.productKey}`);
      if (native) {
        markNativeBoth(native);
        continue;
      }
      if (emittedCatalogProductKeys.has(coverage.productKey)) continue;
    }

    if (catalogAlreadyInstalled(hit, userMcpServers)) continue;

    if (coverage.kind === "product") {
      emittedCatalogProductKeys.add(coverage.productKey);
    }

    const category =
      hit.categories?.length && hit.categories[0]
        ? mapIntegrationsShCategory(hit.categories[0])
        : "other";

    byId.set(`catalog:${hit.domain}`, {
      id: `catalog:${hit.domain}`,
      name: hit.name,
      description: hit.description?.trim() || `Add ${hit.name} as an MCP connector.`,
      iconUrl: hit.icon,
      category,
      source: "mcp",
      status: "available",
      badges: ["MCP"],
      installedDetail: null,
      kind: "catalog_mcp",
      integrationId: null,
      userMcpServerId: null,
      catalogDomain: hit.domain,
      connectedDisplayName: null,
      syncCapable: false,
      popularity: typeof hit.popularity === "number" ? hit.popularity : 0,
    });
  }

  return [...byId.values()].sort((a, b) => {
    const rank = (s: ConnectorStatus) => {
      if (s === "error" || s === "needs_attention") return 0;
      if (s === "installed") return 1;
      return 2;
    };
    const r = rank(a.status) - rank(b.status);
    if (r !== 0) return r;
    return a.name.localeCompare(b.name);
  });
}

