import { OpsIntegrationDetailPage } from "@web/components/ops/ops-integration-detail-page";
import { OPS_INTEGRATION_TABS } from "@web/components/ops/ops-integrations-form";
import { resolveOpsTab } from "@web/components/ops/ops-tab-search";
import { Route } from "./integration.$service";

export function OpsIntegrationDetailRoute() {
  const { service } = Route.useParams();
  const search = Route.useSearch();
  const tab = resolveOpsTab(search, OPS_INTEGRATION_TABS, "service");
  const navigate = Route.useNavigate();
  return (
    <OpsIntegrationDetailPage
      service={service}
      tab={tab}
      onTabChange={(nextTab) => {
        void navigate({
          search: (prev) => ({ ...prev, tab: nextTab === "service" ? undefined : nextTab }),
          replace: true,
        });
      }}
    />
  );
}

