/** Detail payload: public org fields + optional decrypted secrets for ops reveal UI. */
function toOpsOrgDetailRow(row: OrgRecord): OrgPublicRow {
  const base = toOrgPublicRow(row);
  let s3Credentials: OrgPublicRow["s3Credentials"] = null;
  let s3CredentialsStub = false;

  let s3CredentialsError: "decrypt" | "incomplete" | null = null;
  if (row.encryptedS3Credentials?.trim()) {
    const parsed = parseEncryptedOrgS3Payload(row.encryptedS3Credentials, {
      bucketNameFallback: row.s3BucketName,
    });
    s3CredentialsStub = parsed.stub;
    if (parsed.stub) {
      s3Credentials = null;
    } else if (parsed.credentials) {
      s3Credentials = {
        accessKeyId: parsed.credentials.accessKeyId,
        secretAccessKey: parsed.credentials.secretAccessKey,
        region: parsed.credentials.region,
        endpoint: parsed.credentials.endpoint,
      };
    } else {
      s3Credentials = null;
      s3CredentialsError = parsed.error ?? "incomplete";
      console.warn("[ops] org S3 credentials unreadable", {
        orgId: row.id,
        error: s3CredentialsError,
        hasBucketColumn: Boolean(row.s3BucketName?.trim()),
      });
    }
  }

  return {
    ...base,
    s3Credentials,
    s3CredentialsStub,
    s3CredentialsError,
  };
}

