function currentReleaseChannel(requestUrl: string): string | undefined {
  const configured = process.env.GENESIS_RELEASE_CHANNEL?.trim();
  if (configured) return configured;
  const hostname = new URL(requestUrl).hostname.toLowerCase();
  const preview = hostname.match(/^(pr-\d+-(?:edge|stable))\.agentcompany\.com$/);
  if (preview) return preview[1];
  if (hostname === "edge.agentcompany.com") return "edge";
  if (hostname === "app.agentcompany.com") return "stable";
  return undefined;
}

