async function fetchOrgsWithRetry(
  maxAttempts = 3,
): Promise<{ orgs: OpsOrgRow[]; inviteEmailAvailable: boolean }> {
  let lastError: Error | null = null;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const res = await apiFetch("/api/ops/orgs");
      if (!res.ok) {
        // Transient during channel cutover / multi-replica roll (502/503/504).
        if ([502, 503, 504, 0].includes(res.status) && attempt < maxAttempts) {
          await new Promise((r) => setTimeout(r, 400 * attempt));
          continue;
        }
        throw new Error(
          res.status === 403
            ? "You do not have access to Ops organizations"
            : `Could not load organizations (${res.status})`,
        );
      }
      const body = (await res.json()) as {
        orgs: OpsOrgRow[];
        inviteEmailAvailable?: boolean;
      };
      return {
        orgs: body.orgs ?? [],
        // Older servers omit the flag; only force-off when the API says false.
        inviteEmailAvailable: body.inviteEmailAvailable !== false,
      };
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));
      if (attempt < maxAttempts) {
        await new Promise((r) => setTimeout(r, 400 * attempt));
      }
    }
  }
  throw lastError ?? new Error("Could not load organizations");
}

