/** Active integration connections for an org (aggregated across members). */
export async function listOpsIntegrationsForOrg(orgId: string): Promise<OpsOrgIntegrationRow[]> {
  const id = orgId.trim();
  if (!id) return [];

  const rows = await db
    .select({
      integrationId: userIntegration.integrationId,
      name: integration.name,
      description: integration.description,
      userId: userIntegration.userId,
      connectedAt: userIntegration.connectedAt,
    })
    .from(userIntegration)
    .innerJoin(integration, eq(integration.id, userIntegration.integrationId))
    .where(and(eq(userIntegration.orgId, id), eq(userIntegration.status, "active")));

  type Acc = {
    integrationId: string;
    name: string;
    description: string | null;
    users: Set<string>;
    connectionCount: number;
    lastConnectedAt: Date | null;
  };
  const byId = new Map<string, Acc>();
  for (const row of rows) {
    let acc = byId.get(row.integrationId);
    if (!acc) {
      acc = {
        integrationId: row.integrationId,
        name: row.name,
        description: row.description,
        users: new Set(),
        connectionCount: 0,
        lastConnectedAt: null,
      };
      byId.set(row.integrationId, acc);
    }
    acc.connectionCount += 1;
    acc.users.add(row.userId);
    if (!acc.lastConnectedAt || row.connectedAt > acc.lastConnectedAt) {
      acc.lastConnectedAt = row.connectedAt;
    }
  }

  return [...byId.values()]
    .map((acc) => ({
      integrationId: acc.integrationId,
      name: acc.name,
      description: acc.description,
      connectionCount: acc.connectionCount,
      userCount: acc.users.size,
      lastConnectedAt: acc.lastConnectedAt?.toISOString() ?? null,
    }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

