import { cn } from "@web/lib/utils";
import { Eye, EyeOff, Flag } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import type { OpsFeatureFlagRow } from "../../../storage/ops-directory";
import type { OpsOrgRow } from "./ops-orgs-page";

function DetailRow({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div className="grid gap-1 border-b border-border py-3 sm:grid-cols-[12rem_1fr] sm:gap-4">
      <dt className="text-sm text-muted-foreground">{label}</dt>
      <dd className="text-sm text-foreground break-all">{value}</dd>
    </div>
  );
}

function maskSecret(value: string): string {
  if (value.length <= 8) return "••••••••";
  return `${value.slice(0, 4)}${"•".repeat(Math.min(value.length - 8, 24))}${value.slice(-4)}`;
}

function S3CredentialsReveal({
  hasS3Credentials,
  s3Credentials,
  s3CredentialsStub,
  s3CredentialsError,
}: {
  hasS3Credentials: boolean;
  s3Credentials?: OpsOrgRow["s3Credentials"];
  s3CredentialsStub?: boolean;
  s3CredentialsError?: OpsOrgRow["s3CredentialsError"];
}) {
  const [revealed, setRevealed] = useState(false);

  if (!hasS3Credentials) {
    return <span className="text-muted-foreground">Not set</span>;
  }

  if (s3CredentialsStub) {
    const stubLabel = "Local stub (not real object storage)";
    return (
      <div className="flex items-start gap-2">
        <span className={cn("min-w-0 flex-1 font-mono", !revealed && "select-none")}>
          {revealed ? stubLabel : maskSecret(stubLabel)}
        </span>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="size-8 shrink-0"
          aria-label={revealed ? "Hide S3 credentials" : "Show S3 credentials"}
          onClick={() => setRevealed((v) => !v)}
        >
          {revealed ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
        </Button>
      </div>
    );
  }

  if (!s3Credentials) {
    const message =
      s3CredentialsError === "decrypt"
        ? "Stored (could not decrypt — check INTEGRATION_ENCRYPTION_KEY matches the key used at provision)"
        : s3CredentialsError === "incomplete"
          ? "Stored (incomplete credentials in payload)"
          : "Stored (could not read)";
    return <span className="text-muted-foreground">{message}</span>;
  }

  return (
    <div className="flex items-start gap-2">
      <div className={cn("min-w-0 flex-1 space-y-1 font-mono text-xs", !revealed && "select-none")}>
        {revealed ? (
          <>
            <p>
              <span className="text-muted-foreground">Access key · </span>
              {s3Credentials.accessKeyId}
            </p>
            <p>
              <span className="text-muted-foreground">Secret key · </span>
              {s3Credentials.secretAccessKey}
            </p>
            {s3Credentials.region ? (
              <p>
                <span className="text-muted-foreground">Region · </span>
                {s3Credentials.region}
              </p>
            ) : null}
            {s3Credentials.endpoint ? (
              <p>
                <span className="text-muted-foreground">Endpoint · </span>
                {s3Credentials.endpoint}
              </p>
            ) : null}
          </>
        ) : (
          <>
            <p>
              <span className="text-muted-foreground">Access key · </span>
              {maskSecret(s3Credentials.accessKeyId)}
            </p>
            <p>
              <span className="text-muted-foreground">Secret key · </span>
              {maskSecret(s3Credentials.secretAccessKey)}
            </p>
          </>
        )}
      </div>
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="size-8 shrink-0"
        aria-label={revealed ? "Hide S3 credentials" : "Show S3 credentials"}
        onClick={() => setRevealed((v) => !v)}
      >
        {revealed ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
      </Button>
    </div>
  );
}

export function OpsOrgOverview({
  org,
  featureFlags,
}: {
  org: OpsOrgRow;
  featureFlags: OpsFeatureFlagRow[];
}) {
  return (
    <>
      <dl className="max-w-3xl">
        <DetailRow label="Org id" value={<span className="font-mono">{org.id}</span>} />
        <DetailRow
          label="Company URL"
          value={
            org.companyUrl ? (
              <a
                href={org.companyUrl}
                target="_blank"
                rel="noreferrer"
                className="text-primary underline-offset-2 hover:underline"
              >
                {org.companyUrl}
              </a>
            ) : (
              <span className="text-muted-foreground">—</span>
            )
          }
        />
        <DetailRow
          label="Project id"
          value={
            org.agentuityProjectId ? (
              <span className="font-mono">{org.agentuityProjectId}</span>
            ) : (
              <span className="text-muted-foreground">—</span>
            )
          }
        />
        <DetailRow label="Collections DB status" value={org.collectionDatabaseStatus} />
        <DetailRow
          label="S3 bucket"
          value={
            org.s3BucketName ? (
              <span className="font-mono">{org.s3BucketName}</span>
            ) : (
              <span className="text-muted-foreground">—</span>
            )
          }
        />
        <DetailRow
          label="S3 credentials"
          value={
            <S3CredentialsReveal
              hasS3Credentials={Boolean(org.hasS3Credentials)}
              s3Credentials={org.s3Credentials}
              s3CredentialsStub={org.s3CredentialsStub}
              s3CredentialsError={org.s3CredentialsError}
            />
          }
        />
        <DetailRow label="Region" value={org.region ?? "—"} />
        <DetailRow
          label="Provision error"
          value={org.provisionError ?? <span className="text-muted-foreground">None</span>}
        />
        <DetailRow label="Created" value={new Date(org.createdAt).toLocaleString()} />
        <DetailRow label="Updated" value={new Date(org.updatedAt).toLocaleString()} />
      </dl>

      <section className="mt-10 max-w-3xl space-y-3">
        <div className="flex items-center gap-2">
          <Flag className="size-4 text-muted-foreground" />
          <h2 className="text-base font-semibold tracking-tight">Feature flags</h2>
        </div>
        <p className="text-sm text-muted-foreground">
          Flags enabled for every organization or specifically for this one.
        </p>
        {featureFlags.length === 0 ? (
          <p className="text-sm text-muted-foreground">
            No feature flags enabled for this organization.
          </p>
        ) : (
          <ul className="divide-y divide-border border border-border">
            {featureFlags.map((flag) => (
              <li
                key={flag.id}
                className="flex flex-wrap items-start justify-between gap-2 px-4 py-3"
              >
                <div className="min-w-0">
                  <p className="text-sm font-medium">{flag.name}</p>
                  <p className="text-xs text-muted-foreground">{flag.description}</p>
                  <p className="mt-1 font-mono text-xs text-muted-foreground">{flag.id}</p>
                </div>
                <Badge variant="secondary">
                  {flag.source === "global" ? "All orgs" : "This org"}
                </Badge>
              </li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

