/**
 * Catalog data for Connectors marketplace: user MCP list + integrations.sh pages.
 * Search is server-side; totals use API `total` / `matchTotal` (not loaded-page length).
 */

import {
  listUserMcpServers,
  searchUserMcpCatalog,
  type UserMcpCatalogSearchHit,
} from "@web/lib/user-mcp-api";
import { useCallback, useEffect, useRef, useState } from "react";
import type { UserMcpServerListItem } from "./types";

const CATALOG_PAGE_SIZE = 48;

export type UseConnectorsCatalogResult = {
  userMcpServers: UserMcpServerListItem[];
  userMcpLoading: boolean;
  catalogHits: UserMcpCatalogSearchHit[];
  /** Full integrations.sh MCP size. */
  catalogTotal: number;
  /** Matches for current search (or full total when browsing). */
  catalogMatchTotal: number;
  catalogHasMore: boolean;
  catalogLoading: boolean;
  catalogLoadingMore: boolean;
  catalogError: string | null;
  catalogReady: boolean;
  loadUserMcp: () => Promise<void>;
  loadMoreCatalog: () => void;
  /** Browse badge: public MCP match total + available natives are layered by the caller. */
  setSearchQuery: (q: string) => void;
  searchQuery: string;
};

function toListItem(server: {
  id: string;
  slug: string;
  displayName: string;
  url: string;
  description?: string | null;
  iconUrl?: string | null;
  status: string;
  lastErrorCode: string | null;
  authKind: string;
  headerName?: string | null;
  headerTemplate?: string | null;
  lastTools?: string[] | null;
  lastProbeAt?: string | null;
}): UserMcpServerListItem {
  return {
    id: server.id,
    slug: server.slug,
    displayName: server.displayName,
    url: server.url,
    description: server.description?.trim() || null,
    iconUrl: server.iconUrl ?? null,
    status: server.status,
    lastErrorCode: server.lastErrorCode,
    authKind: server.authKind,
    headerName: server.headerName?.trim() || null,
    headerTemplate: server.headerTemplate?.trim() || null,
    lastTools: Array.isArray(server.lastTools)
      ? server.lastTools.filter((t): t is string => typeof t === "string" && t.trim().length > 0)
      : [],
    lastProbeAt: server.lastProbeAt ?? null,
  };
}

export function useConnectorsCatalog(): UseConnectorsCatalogResult {
  const [userMcpServers, setUserMcpServers] = useState<UserMcpServerListItem[]>([]);
  const [userMcpLoading, setUserMcpLoading] = useState(false);
  const [catalogHits, setCatalogHits] = useState<UserMcpCatalogSearchHit[]>([]);
  const [catalogTotal, setCatalogTotal] = useState(0);
  const [catalogMatchTotal, setCatalogMatchTotal] = useState(0);
  const [catalogHasMore, setCatalogHasMore] = useState(false);
  const [catalogLoading, setCatalogLoading] = useState(false);
  const [catalogLoadingMore, setCatalogLoadingMore] = useState(false);
  const [catalogError, setCatalogError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const catalogFetchGen = useRef(0);

  const loadUserMcp = useCallback(async () => {
    setUserMcpLoading(true);
    try {
      const servers = await listUserMcpServers();
      setUserMcpServers(servers.map(toListItem));
    } catch (error) {
      // Natives still show; keep prior user MCP list empty only on hard failure.
      setUserMcpServers([]);
      console.error(
        "[connectors] failed to load user MCP servers",
        error instanceof Error ? error.message : error,
      );
    } finally {
      setUserMcpLoading(false);
    }
  }, []);

  const loadCatalogPage = useCallback(
    async (q: string, offset: number, mode: "replace" | "append") => {
      const gen = ++catalogFetchGen.current;
      if (mode === "replace") {
        setCatalogLoading(true);
        setCatalogError(null);
      } else {
        setCatalogLoadingMore(true);
      }
      try {
        const page = await searchUserMcpCatalog({
          query: q,
          limit: CATALOG_PAGE_SIZE,
          offset,
        });
        if (gen !== catalogFetchGen.current) return;
        setCatalogHits((prev) => {
          if (mode === "replace") return page.results;
          const seen = new Set(prev.map((h) => h.domain));
          const merged = [...prev];
          for (const hit of page.results) {
            if (seen.has(hit.domain)) continue;
            seen.add(hit.domain);
            merged.push(hit);
          }
          return merged;
        });
        setCatalogTotal(page.total);
        setCatalogMatchTotal(page.matchTotal);
        setCatalogHasMore(page.hasMore);
      } catch (error) {
        if (gen !== catalogFetchGen.current) return;
        setCatalogError(error instanceof Error ? error.message : "Could not load the catalog.");
        if (mode === "replace") {
          setCatalogHits([]);
          setCatalogHasMore(false);
        }
      } finally {
        if (gen === catalogFetchGen.current) {
          setCatalogLoading(false);
          setCatalogLoadingMore(false);
        }
      }
    },
    [],
  );

  useEffect(() => {
    void loadUserMcp();
  }, [loadUserMcp]);

  useEffect(() => {
    const handle = window.setTimeout(() => {
      void loadCatalogPage(searchQuery, 0, "replace");
    }, 250);
    return () => window.clearTimeout(handle);
  }, [searchQuery, loadCatalogPage]);

  const loadMoreCatalog = useCallback(() => {
    if (catalogLoading || catalogLoadingMore || !catalogHasMore) return;
    void loadCatalogPage(searchQuery, catalogHits.length, "append");
  }, [
    catalogHasMore,
    catalogHits.length,
    catalogLoading,
    catalogLoadingMore,
    loadCatalogPage,
    searchQuery,
  ]);

  return {
    userMcpServers,
    userMcpLoading,
    catalogHits,
    catalogTotal,
    catalogMatchTotal,
    catalogHasMore,
    catalogLoading,
    catalogLoadingMore,
    catalogError,
    catalogReady: catalogTotal > 0,
    loadUserMcp,
    loadMoreCatalog,
    setSearchQuery,
    searchQuery,
  };
}

/** Client-safe API-key catalog ids (no server/db imports). */
export const API_KEY_INTEGRATION_IDS = ["shopmonkey"] as const;

export type ApiKeyIntegrationId = (typeof API_KEY_INTEGRATION_IDS)[number];

export function isApiKeyIntegrationId(integrationId: string): boolean {
  const normalized = integrationId.trim().toLowerCase();
  return (API_KEY_INTEGRATION_IDS as readonly string[]).includes(normalized);
}

