  type SortingState,
  useReactTable,
  type VisibilityState,
} from "@tanstack/react-table";
import { useState } from "react";

export type OpsDataTableSearchHaystack<TData> = (row: TData) => Array<string | null | undefined>;

type OpsDataTableBaseArgs<TData> = {
  data: TData[];
  columns: ColumnDef<TData>[];
  getRowId?: (row: TData) => string;
  defaultSorting?: SortingState;
  defaultColumnVisibility?: VisibilityState;
  defaultPageSize?: number;
  searchHaystack?: OpsDataTableSearchHaystack<TData>;
  enableSorting?: boolean;
  enableColumnResizing?: boolean;
  /** Server-paginated lists supply their total page count. */
  manualPagination?: boolean;
  pageCount?: number;
  /** Server-filtered lists keep the URL-backed search value without filtering the page again. */
  manualFiltering?: boolean;
  /** Controlled search string (URL). When omitted, search is local. */
  search?: string;
  onSearchChange?: (value: string) => void;
};

/** URL-backed lists must pass both pagination state and its writer. */
type OpsDataTableControlledPagination = {
  pagination: PaginationState;
  onPaginationChange: OnChangeFn<PaginationState>;
};

type OpsDataTableLocalPagination = {
  pagination?: undefined;
  onPaginationChange?: undefined;
};

export type UseOpsDataTableArgs<TData> = OpsDataTableBaseArgs<TData> &
  (OpsDataTableControlledPagination | OpsDataTableLocalPagination);

/**
 * Shared TanStack table state for Ops list screens.
 *
 * Search always goes through the table `globalFilter` + `searchHaystack`.
 * Extra dimensions (status, type) belong in `data` (pre-filter) or column filters —
 * never as a second parallel search string.
 *
 * Local search resets page index inside `setSearch`. Controlled search must reset
 * page in the parent writer (e.g. URL `writeSearch({ q, pageIndex: 0 })`).
 *
 * Controlled pagination requires both `pagination` and `onPaginationChange`.
 */
export function useOpsDataTable<TData>({
  data,
  columns,
  getRowId,
  defaultSorting = [],
  defaultColumnVisibility = {},
  defaultPageSize = 25,
  searchHaystack,
  enableSorting = true,
  enableColumnResizing = true,
  manualPagination = false,
  pageCount,
  manualFiltering = false,
  pagination: controlledPagination,
  onPaginationChange: controlledOnPaginationChange,
  search: controlledSearch,
  onSearchChange: controlledOnSearchChange,
}: UseOpsDataTableArgs<TData>) {
  if ((controlledPagination !== undefined) !== (controlledOnPaginationChange !== undefined)) {
    throw new Error(
      "useOpsDataTable: pass both pagination and onPaginationChange for URL control, or neither",
    );
  }
  if (controlledSearch !== undefined && controlledOnSearchChange === undefined) {
    throw new Error(
      "useOpsDataTable: controlled search requires onSearchChange (parent must own page reset)",
    );
  }

  const [sorting, setSorting] = useState<SortingState>(defaultSorting);
  const [columnFilters, setColumnFilters] = useState<ColumnFiltersState>([]);
  const [columnVisibility, setColumnVisibility] =
    useState<VisibilityState>(defaultColumnVisibility);
  const [localSearch, setLocalSearch] = useState("");
  const [localPagination, setLocalPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: defaultPageSize,
  });

  const searchControlled = controlledSearch !== undefined;
  const search = searchControlled ? controlledSearch : localSearch;
  const setSearch = (value: string) => {
    if (searchControlled) {
      // Parent owns URL (and must reset pageIndex there).
      controlledOnSearchChange?.(value);
      return;
    }
    setLocalSearch(value);
    setLocalPagination((prev) => (prev.pageIndex === 0 ? prev : { ...prev, pageIndex: 0 }));
  };

  const paginationControlled = controlledPagination !== undefined;
  const pagination = paginationControlled ? controlledPagination : localPagination;
  const onPaginationChange: OnChangeFn<PaginationState> = paginationControlled
    ? controlledOnPaginationChange
    : setLocalPagination;

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      globalFilter: search,
      pagination,
    },
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onColumnVisibilityChange: setColumnVisibility,
    onGlobalFilterChange: (updater) => {
      const next = typeof updater === "function" ? updater(search) : updater;
      setSearch(String(next ?? ""));
    },
    onPaginationChange,
    enableSorting,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    manualFiltering,
    manualPagination,
    pageCount,
    getRowId,
    globalFilterFn: searchHaystack
      ? (row, _columnId, filterValue) => {
          const q = String(filterValue ?? "")
            .trim()
            .toLowerCase();
          if (!q) return true;
          const haystack = searchHaystack(row.original).filter(Boolean).join(" ").toLowerCase();
          return haystack.includes(q);
        }
      : "includesString",
    enableColumnResizing,
    columnResizeMode: enableColumnResizing ? "onChange" : undefined,
  });

  return {
    table,
    search,
    setSearch,
  };
}

