import { apiFetch } from "@web/lib/api-fetch";
import { Building2, Check, ChevronsUpDown, Loader2, Plus, X } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { linesToList } from "./ops-integrations-form";

type OpsAllowlistOrg = {
  id: string;
  name: string;
  status: string;
};

function parseOrgs(body: unknown): OpsAllowlistOrg[] {
  const orgs = (body as { orgs?: OpsAllowlistOrg[] } | null)?.orgs;
  return Array.isArray(orgs) ? orgs : [];
}

export function OpsIntegrationAllowlist({
  value,
  onChange,
}: {
  value: string;
  onChange: (value: string) => void;
}) {
  const [orgs, setOrgs] = useState<OpsAllowlistOrg[]>([]);
  const [loading, setLoading] = useState(true);
  const [open, setOpen] = useState(false);
  const [manualId, setManualId] = useState("");
  const selectedIds = useMemo(() => linesToList(value), [value]);
  const selectedSet = useMemo(() => new Set(selectedIds), [selectedIds]);
  const orgById = useMemo(() => new Map(orgs.map((org) => [org.id, org])), [orgs]);

  useEffect(() => {
    let cancelled = false;
    void apiFetch("/api/ops/orgs")
      .then(async (response) => {
        if (!response.ok) throw new Error("Could not load organizations");
        const body: unknown = await response.json();
        if (!cancelled) setOrgs(parseOrgs(body));
      })
      .catch(() => {
        if (!cancelled) toast.error("Could not load organizations for the allowlist");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  function update(nextIds: string[]) {
    onChange([...new Set(nextIds)].join("\n"));
  }

  function add(orgId: string) {
    update([...selectedIds, orgId]);
    setOpen(false);
  }

  function remove(orgId: string) {
    update(selectedIds.filter((id) => id !== orgId));
  }

  function addManualId() {
    const orgId = manualId.trim();
    if (!orgId || selectedSet.has(orgId)) return;
    add(orgId);
    setManualId("");
  }

  const availableOrgs = orgs.filter((org) => !selectedSet.has(org.id));

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap gap-2">
        <Popover open={open} onOpenChange={setOpen}>
          <PopoverTrigger asChild>
            <Button type="button" variant="outline" size="sm" className="justify-between gap-2">
              {loading ? <Loader2 className="size-3.5 animate-spin" /> : <Building2 />}
              Add organization
              <ChevronsUpDown className="size-3.5 text-muted-foreground" />
            </Button>
          </PopoverTrigger>
          <PopoverContent align="start" className="w-[24rem] max-w-[calc(100vw-2rem)] gap-0 p-0">
            <Command>
              <CommandInput placeholder="Search by organization name or id…" />
              <CommandList>
                <CommandEmpty>No organizations found.</CommandEmpty>
                {availableOrgs.map((org) => (
                  <CommandItem
                    key={org.id}
                    value={`${org.name} ${org.id}`}
                    onSelect={() => add(org.id)}
                  >
                    <Building2 className="size-4 text-muted-foreground" />
                    <span className="min-w-0 flex-1">
                      <span className="block truncate">{org.name}</span>
                      <span className="block truncate font-mono text-xs text-muted-foreground">
                        {org.id}
                      </span>
                    </span>
                    <span className="text-xs text-muted-foreground">{org.status}</span>
                  </CommandItem>
                ))}
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>

        <div className="flex min-w-64 flex-1 gap-2">
          <Input
            value={manualId}
            onChange={(event) => setManualId(event.target.value)}
            onKeyDown={(event) => {
              if (event.nativeEvent.isComposing) return;
              if (event.key === "Enter") {
                event.preventDefault();
                addManualId();
              }
            }}
            placeholder="Or enter an org id"
            aria-label="Organization id"
            className="font-mono text-xs"
          />
          <Button
            type="button"
            variant="outline"
            size="icon"
            disabled={!manualId.trim() || selectedSet.has(manualId.trim())}
            onClick={addManualId}
            aria-label="Add organization id"
          >
            <Plus />
          </Button>
        </div>
      </div>

      {selectedIds.length === 0 ? (
        <div className="rounded-sm border border-dashed border-border px-4 py-6 text-center text-sm text-muted-foreground">
          You haven&apos;t allowlisted any organizations yet.
        </div>
      ) : (
        <div className="divide-y divide-sidebar-border/50 rounded-sm border border-border">
          {selectedIds.map((orgId) => {
            const org = orgById.get(orgId);
            return (
              <div key={orgId} className="flex items-center gap-3 px-3 py-2.5">
                <span className="flex size-8 shrink-0 items-center justify-center rounded-sm bg-muted">
                  {org ? (
                    <Building2 className="size-4 text-muted-foreground" />
                  ) : (
                    <Check className="size-4 text-muted-foreground" />
                  )}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-medium">
                    {org?.name ?? "Unknown organization"}
                  </span>
                  <span className="block truncate font-mono text-xs text-muted-foreground">
                    {orgId}
                  </span>
                </span>
                {org ? <span className="text-xs text-muted-foreground">{org.status}</span> : null}
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-8 shrink-0"
                  onClick={() => remove(orgId)}
                  aria-label={`Remove ${org?.name ?? orgId} from allowlist`}
                >
                  <X className="size-4" />
                </Button>
              </div>
            );
          })}
        </div>
      )}
      <p className="text-xs text-muted-foreground">
        You&apos;ve allowed {selectedIds.length} organization
        {selectedIds.length === 1 ? "" : "s"} to use this connection while it is experimental.
      </p>
    </div>
  );
}

