export function OpsOrgDetailPage({
  orgId,
  tab,
  onTabChange,
}: {
  orgId: string;
  tab: string;
  onTabChange: (tab: string) => void;
}) {
  const navigate = useNavigate();
  const [org, setOrg] = useState<OpsOrgRow | null>(null);
  const [members, setMembers] = useState<OpsOrgMember[]>([]);
  const [sessionCount, setSessionCount] = useState(0);
  const [featureFlags, setFeatureFlags] = useState<OpsFeatureFlagRow[]>([]);
  const [viewAsUser, setViewAsUser] = useState<OpsUserListRow | null>(null);
  const [viewAsStarting, setViewAsStarting] = useState(false);
  const [loading, setLoading] = useState(true);
  const [inviting, setInviting] = useState(false);
  const [sendingInviteUserId, setSendingInviteUserId] = useState<string | null>(null);
  const [retrying, setRetrying] = useState(false);
  const [deprovisioning, setDeprovisioning] = useState(false);
  const [deprovisionDialogOpen, setDeprovisionDialogOpen] = useState(false);
  const [inviteEmailAvailable, setInviteEmailAvailable] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiFetch(`/api/ops/orgs/${encodeURIComponent(orgId)}`);
      if (!res.ok) throw new Error("Could not load organization");
      const body = (await res.json()) as {
        org: OpsOrgRow;
        members?: OpsOrgMember[];
        sessionCount?: number;
        featureFlags?: OpsFeatureFlagRow[];
        inviteEmailAvailable?: boolean;
      };
      setOrg(body.org);
      setMembers(body.members ?? []);
      setSessionCount(body.sessionCount ?? 0);
      setFeatureFlags(body.featureFlags ?? []);
      setInviteEmailAvailable(body.inviteEmailAvailable !== false);
    } catch {
      setOrg(null);
      setMembers([]);
      setSessionCount(0);
      setFeatureFlags([]);
      toast.error("Could not load organization");
    } finally {
      setLoading(false);
    }
  }, [orgId]);

  useEffect(() => {
    void load();
  }, [load]);

  const roleByUserId = useMemo(() => {
    const map = new Map<string, string>();
    for (const member of members) {
      map.set(member.userId, member.role);
    }
    return map;
  }, [members]);

  async function confirmViewAs() {
    if (!viewAsUser) return;
    setViewAsStarting(true);
    try {
      const res = await apiFetch("/api/ops/impersonate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ orgId, userId: viewAsUser.id }),
      });
      const body = (await res.json().catch(() => null)) as { error?: string } | null;
      if (!res.ok) {
        throw new Error(body?.error || "Could not start view-as");
      }
      await clearGenesisClientCaches({ bestEffort: true });
      getGenesisQueryClient().clear();
      window.location.assign("/");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not start view-as");
      setViewAsStarting(false);
    }
  }

  async function onInvite(payload: OpsOrgInvitePayload) {
    if (org?.status === "provisioning") {
      toast.error("This organization is still provisioning. Invite people after it is active.");
      return;
    }
    setInviting(true);
    try {
      const res = await apiFetch(`/api/ops/orgs/${encodeURIComponent(orgId)}/members`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
