/**
 * Persist ops detail tabs in the URL (`?tab=…`) so reload restores selection.
 * `tab` is optional in the route search so plain links keep working.
 */

export type OpsTabSearch = {
  tab?: string;
};

export function parseOpsTabSearch(
  search: Record<string, unknown>,
  allowed: readonly string[],
  fallback: string,
): OpsTabSearch {
  const raw = typeof search.tab === "string" ? search.tab.trim() : "";
  if (raw && allowed.includes(raw)) return { tab: raw };
  // Omit default from the URL when not set; pages use `fallback` themselves.
  void fallback;
  return {};
}

export function resolveOpsTab(
  search: OpsTabSearch | undefined,
  allowed: readonly string[],
  fallback: string,
): string {
  const raw = search?.tab?.trim() || "";
  if (raw && allowed.includes(raw)) return raw;
  return fallback;
}

import { apiFetch } from "@web/lib/api-fetch";
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";

/**
 * Shared load lifecycle for ops list tables. Pages that need a header count
 * read `rows.length` / `loading` from here instead of callback plumbing.
 */
export function useOpsList<T>({
  path,
  parseRows,
  orgId,
  userId,
  errorMessage,
  enabled = true,
}: {
  path: string;
  parseRows: (body: unknown) => T[];
  orgId?: string | null;
  userId?: string | null;
  errorMessage: string;
  /** When false, skip fetch (controlled parent owns the rows). */
  enabled?: boolean;
}): {
  rows: T[];
  loading: boolean;
  reload: () => Promise<void>;
} {
  const [rows, setRows] = useState<T[]>([]);
  const [loading, setLoading] = useState(enabled);

  const reload = useCallback(async () => {
    if (!enabled) return;
    setLoading(true);
    try {
      const params = new URLSearchParams();
      if (orgId?.trim()) params.set("orgId", orgId.trim());
      if (userId?.trim()) params.set("userId", userId.trim());
      const qs = params.toString() ? `?${params.toString()}` : "";
      const res = await apiFetch(`${path}${qs}`);
      if (!res.ok) throw new Error(errorMessage);
      const body: unknown = await res.json();
      setRows(parseRows(body));
    } catch {
      setRows([]);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  }, [enabled, errorMessage, orgId, parseRows, path, userId]);

  useEffect(() => {
    void reload();
  }, [reload]);

  return { rows, loading, reload };
}

