import type { ColumnDef } from "@tanstack/react-table";
import { DataTableColumnHeader } from "@web/components/data-table/data-table-column-header";
import { apiFetch } from "@web/lib/api-fetch";
import { Building2 } from "lucide-react";
import { useMemo } from "react";
import { Badge } from "@/components/ui/badge";
import type { OpsIntegrationOrgRow } from "../../../storage/ops-directory";
import { formatOpsWhen } from "./ops-format";
import { OpsListTableEmpty, OpsListTableFrame, OpsListTableSkeleton } from "./ops-list-table-frame";
import { useOpsDataTable } from "./use-ops-data-table";
import { useOpsList } from "./use-ops-list";

const parseOrgs = (body: unknown): OpsIntegrationOrgRow[] => {
  const orgs = (body as { orgs?: OpsIntegrationOrgRow[] } | null)?.orgs;
  return Array.isArray(orgs) ? orgs : [];
};

const COLUMN_LABELS: Record<string, string> = {
  orgName: "Organization",
  orgId: "Id",
  orgStatus: "Status",
  userCount: "Users",
  connectionCount: "Connections",
  lastConnectedAt: "Last connected",
};

export function OpsIntegrationOrgsPanel({
  service,
  onOpenOrg,
}: {
  service: string;
  onOpenOrg: (orgId: string) => void;
}) {
  const { rows, loading } = useOpsList<OpsIntegrationOrgRow>({
    path: `/api/ops/integrations/${encodeURIComponent(service)}/orgs`,
    parseRows: parseOrgs,
    errorMessage: "Could not load organizations using this integration",
  });

  const columns = useMemo<ColumnDef<OpsIntegrationOrgRow>[]>(
    () => [
      {
        id: "orgName",
        accessorKey: "orgName",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Organization" />,
        cell: ({ row }) => (
          <div className="flex min-w-0 items-center gap-2.5 py-0.5">
            <Building2 className="size-4 shrink-0 text-muted-foreground" />
            <div className="min-w-0">
              <div className="truncate font-medium">{row.original.orgName}</div>
              <div className="truncate font-mono text-xs text-muted-foreground">
                {row.original.orgId}
              </div>
            </div>
          </div>
        ),
        size: 260,
        minSize: 180,
        enableHiding: false,
        enableResizing: true,
      },
      {
        id: "orgStatus",
        accessorKey: "orgStatus",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Status" />,
        cell: ({ row }) => <Badge variant="secondary">{row.original.orgStatus}</Badge>,
        size: 120,
        enableResizing: true,
      },
      {
        id: "userCount",
        accessorKey: "userCount",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Users" />,
        cell: ({ row }) => <span className="tabular-nums">{row.original.userCount}</span>,
        size: 90,
        enableResizing: true,
      },
      {
        id: "connectionCount",
        accessorKey: "connectionCount",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Connections" />,
        cell: ({ row }) => <span className="tabular-nums">{row.original.connectionCount}</span>,
        size: 110,
        enableResizing: true,
      },
      {
        id: "lastConnectedAt",
        accessorFn: (row) => row.lastConnectedAt ?? "",
        header: ({ column }) => <DataTableColumnHeader column={column} title="Last connected" />,
        cell: ({ row }) => (
          <span className="whitespace-nowrap text-muted-foreground">
            {formatOpsWhen(row.original.lastConnectedAt)}
          </span>
        ),
        sortingFn: "datetime",
        size: 170,
        enableResizing: true,
      },
    ],
    [],
  );

  const { table, search, setSearch } = useOpsDataTable({
    data: rows,
    columns,
    getRowId: (row) => row.orgId,
    defaultSorting: [{ id: "orgName", desc: false }],
    defaultColumnVisibility: { orgId: false },
    searchHaystack: (row) => [row.orgName, row.orgId, row.orgStatus],
  });

  if (loading) return <OpsListTableSkeleton />;
  if (rows.length === 0) {
    return (
      <OpsListTableEmpty
        icon={Building2}
        label="No organizations are using this integration."
        description="Active connections are aggregated by organization."
      />
    );
  }

  return (
    <OpsListTableFrame
      table={table}
      totalRowCount={rows.length}
      search={search}
      onSearchChange={setSearch}
      searchPlaceholder="Search organizations"
      searchAriaLabel="Search organizations using this integration"
      columnLabels={COLUMN_LABELS}
      emptySearchMessage="No organizations match your search."
      onRowClick={(row) => onOpenOrg(row.orgId)}
    />
  );
}

