import type { ConnectorCategoryId } from "./types";

export const CONNECTOR_CATEGORIES: ReadonlyArray<{
  id: ConnectorCategoryId;
  label: string;
}> = [
  { id: "productivity", label: "Productivity" },
  { id: "engineering", label: "Engineering" },
  { id: "sales", label: "Sales" },
  { id: "finance", label: "Finance" },
  { id: "marketing", label: "Marketing" },
  { id: "communication", label: "Communication" },
  { id: "other", label: "Other" },
];

/** Best-effort map for broker integration ids until catalog carries categories. */
const NATIVE_CATEGORY_BY_ID: Readonly<Record<string, ConnectorCategoryId>> = {
  linear: "engineering",
  github: "engineering",
  notion: "productivity",
  todoist: "productivity",
  calcom: "productivity",
  slack: "communication",
  hubspot: "sales",
  attio: "sales",
  salesforce: "sales",
  apollo: "sales",
  mercury: "finance",
  gusto: "finance",
  wave: "finance",
  xero: "finance",
  quickbooks: "finance",
  jobber: "other",
  printavo: "other",
  imap: "communication",
  shopmonkey: "other",
  google: "productivity",
  spotify: "other",
  meta: "marketing",
  "google-business": "marketing",
};

export function categoryForNativeIntegrationId(id: string): ConnectorCategoryId {
  return NATIVE_CATEGORY_BY_ID[id.trim().toLowerCase()] ?? "other";
}

/** Map integrations.sh-style category slugs into Genesis product categories. */
export function mapIntegrationsShCategory(raw: string | null | undefined): ConnectorCategoryId {
  const key = (raw ?? "").trim().toLowerCase();
  if (!key) return "other";
  if (key.includes("sales") || key === "crm") return "sales";
  if (key.includes("market")) return "marketing";
  if (key.includes("dev") || key.includes("engineer") || key.includes("devops")) {
    return "engineering";
  }
  if (key.includes("finance") || key.includes("account") || key.includes("payroll")) {
    return "finance";
  }
  if (key.includes("communicat") || key.includes("messag") || key.includes("chat")) {
    return "communication";
  }
  if (key.includes("productiv") || key.includes("project") || key.includes("docs")) {
    return "productivity";
  }
  return "other";
}

export function categoryLabel(id: ConnectorCategoryId): string {
  return CONNECTOR_CATEGORIES.find((c) => c.id === id)?.label ?? id;
}

