import { useNavigate } from "@tanstack/react-router";
import type { ColumnDef } from "@tanstack/react-table";
import { DataTableColumnHeader } from "@web/components/data-table/data-table-column-header";
import { Plug } from "lucide-react";
import { useMemo } from "react";
import type { OpsOrgIntegrationRow } from "../../../storage/ops-directory";
import { formatOpsWhen } from "./ops-format";
import { OpsListTableEmpty, OpsListTableFrame, OpsListTableSkeleton } from "./ops-list-table-frame";
import { useOpsDataTable } from "./use-ops-data-table";
import { useOpsList } from "./use-ops-list";

export type { OpsOrgIntegrationRow };

const COLUMN_LABELS: Record<string, string> = {
  name: "Integration",
  integrationId: "Id",
  userCount: "Users",
  connectionCount: "Connections",
  lastConnectedAt: "Last connected",
};

const parseIntegrations = (body: unknown): OpsOrgIntegrationRow[] => {
  const integrations = (body as { integrations?: OpsOrgIntegrationRow[] } | null)?.integrations;
  return Array.isArray(integrations) ? integrations : [];
};

export function OpsOrgIntegrationsPanel({ orgId }: { orgId: string }) {
  const navigate = useNavigate();
  const { rows, loading } = useOpsList<OpsOrgIntegrationRow>({
    path: `/api/ops/orgs/${encodeURIComponent(orgId)}/integrations`,
    parseRows: parseIntegrations,
    errorMessage: "Could not load integrations",
  });

  const columns = useMemo<ColumnDef<OpsOrgIntegrationRow>[]>(
    () => [
      {
        id: "name",
