export async function getOpsUserDetail(userId: string): Promise<OpsUserDetail | null> {
  const id = userId.trim();
  if (!id) return null;

  const [user] = await db
    .select({
      id: appUser.id,
      name: appUser.name,
      email: appUser.email,
      lastLoginAt: appUser.lastLoginAt,
      lastActiveOrgId: appUser.lastActiveOrgId,
      createdAt: appUser.createdAt,
    })
    .from(appUser)
    .where(and(eq(appUser.id, id), activeUser()))
    .limit(1);
  if (!user) return null;

  const memberships = await db
    .select({
      membershipId: orgMembership.id,
      orgId: org.id,
      orgName: org.name,
      role: orgMembership.role,
      joinedAt: orgMembership.createdAt,
    })
    .from(orgMembership)
    .innerJoin(org, eq(org.id, orgMembership.orgId))
    .where(eq(orgMembership.userId, id))
    .orderBy(org.name);

  const { listUserRoleAssignments } = await import("./access-control");
  const membershipRows = await Promise.all(
    memberships.map(async (m) => {
      let accessRoles: OpsUserAccessRole[] = [];
      try {
        const assignments = await listUserRoleAssignments(id, m.orgId);
        accessRoles = assignments.map((row) => ({
          slug: row.roleSlug,
          name: row.roleName,
          isSystem: row.isSystem,
        }));
      } catch {
        accessRoles = [];
      }
      return {
        membershipId: m.membershipId,
        orgId: m.orgId,
        orgName: m.orgName,
        role: m.role,
        joinedAt: m.joinedAt.toISOString(),
        accessRoles,
      };
    }),
  );

  return {
    id: user.id,
    name: user.name,
    email: user.email,
    lastLoginAt: user.lastLoginAt?.toISOString() ?? null,
    lastActiveOrgId: user.lastActiveOrgId,
    createdAt: user.createdAt.toISOString(),
    memberships: membershipRows,
  };
}

export async function listOpsSessions(options?: {
  orgId?: string | null;
  userId?: string | null;
  status?: string | null;
  kind?: string | null;
  updatedSince?: Date | null;
  feedback?: "negative" | "any" | null;
  limit?: number;
}): Promise<OpsSessionListRow[]> {
  const orgFilter = options?.orgId?.trim() || null;
  const userFilter = options?.userId?.trim() || null;
  const statusFilter = options?.status?.trim() || null;
  const kindFilter = options?.kind?.trim() || null;
  const feedbackFilter = options?.feedback ?? null;
  const limit = Math.min(Math.max(options?.limit ?? 200, 1), 1000);

  const filters = [activeSession(), opsActivitySessionKindSql()];
  if (orgFilter) filters.push(eq(session.orgId, orgFilter));
  if (userFilter) filters.push(eq(session.userId, userFilter));
  if (statusFilter) filters.push(eq(session.status, statusFilter));
  if (kindFilter) filters.push(eq(session.kind, kindFilter));
  if (options?.updatedSince) filters.push(gte(session.updatedAt, options.updatedSince));
  if (feedbackFilter) {
    const feedbackFilters = [eq(sessionMessageFeedback.sessionId, session.id)];
    if (feedbackFilter === "negative") {
      feedbackFilters.push(eq(sessionMessageFeedback.rating, "down"));
    }
    filters.push(
      exists(
        db
          .select({ id: sessionMessageFeedback.id })
          .from(sessionMessageFeedback)
          .where(and(...feedbackFilters)),
      ),
    );
  }

  const rows = await db
    .select({
      id: session.id,
      title: session.title,
      orgId: session.orgId,
      orgName: org.name,
      userId: session.userId,
      userEmail: appUser.email,
      userName: appUser.name,
      kind: session.kind,
      status: session.status,
      sessionStatus: session.sessionStatus,
      createdAt: session.createdAt,
      updatedAt: session.updatedAt,
    })
    .from(session)
    .innerJoin(org, eq(org.id, session.orgId))
    .leftJoin(appUser, eq(appUser.id, session.userId))
    .where(and(...filters))
    .orderBy(desc(session.createdAt))
    .limit(limit);

  return rows.map((row) => ({
    id: row.id,
    title: row.title,
    orgId: row.orgId,
    orgName: row.orgName,
    userId: row.userId,
    userEmail: row.userEmail,
    userName: row.userName,
    kind: row.kind,
    status: row.status,
    sessionStatus: row.sessionStatus,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  }));
}

