/** Organizations with active connections for an integration (aggregated across members). */
export async function listOpsOrgsForIntegration(
  integrationId: string,
): Promise<OpsIntegrationOrgRow[]> {
  const id = integrationId.trim();
  if (!id) return [];

  const rows = await db
    .select({
      orgId: userIntegration.orgId,
      orgName: org.name,
      orgStatus: org.status,
      userId: userIntegration.userId,
      connectedAt: userIntegration.connectedAt,
    })
    .from(userIntegration)
    .innerJoin(org, eq(org.id, userIntegration.orgId))
    .where(and(eq(userIntegration.integrationId, id), eq(userIntegration.status, "active")));

  type Acc = {
    orgId: string;
    orgName: string;
    orgStatus: string;
    users: Set<string>;
    connectionCount: number;
    lastConnectedAt: Date | null;
  };
  const byOrg = new Map<string, Acc>();
  for (const row of rows) {
    let acc = byOrg.get(row.orgId);
    if (!acc) {
      acc = {
        orgId: row.orgId,
        orgName: row.orgName,
        orgStatus: row.orgStatus,
        users: new Set(),
        connectionCount: 0,
        lastConnectedAt: null,
      };
      byOrg.set(row.orgId, acc);
    }
    acc.connectionCount += 1;
    acc.users.add(row.userId);
    if (!acc.lastConnectedAt || row.connectedAt > acc.lastConnectedAt) {
      acc.lastConnectedAt = row.connectedAt;
    }
  }

  return [...byOrg.values()]
    .map((acc) => ({
      orgId: acc.orgId,
      orgName: acc.orgName,
      orgStatus: acc.orgStatus,
      connectionCount: acc.connectionCount,
      userCount: acc.users.size,
      lastConnectedAt: acc.lastConnectedAt?.toISOString() ?? null,
    }))
    .sort((a, b) => a.orgName.localeCompare(b.orgName));
}

