/**
 * Drizzle schema: integration domain.
 */

import { boolean, index, jsonb, pgTable, text, timestamp, unique } from "drizzle-orm/pg-core";
import type { IntegrationOAuthConfig } from "../../domain/integration";
import { appUser } from "./core";
export const integration = pgTable("integration", {
  id: text("id").primaryKey(), // human-readable slug: "linear", "github"
  name: text("name").notNull(),
  description: text("description"),
  authType: text("auth_type").notNull().default("oauth"),
  oauthConfig: jsonb("oauth_config").$type<IntegrationOAuthConfig>(),
  dcrCredentials: text("dcr_credentials"),
  mcpConfig: jsonb("mcp_config").notNull().$type<
    | {
        type: "none";
      }
    | {
        type: "remote";
        url: string;
        transport: string;
        headerMapping: Record<string, string>;
      }
    | {
        type: "local";
        command: string;
        args: string[];
        transport: string;
        envMapping: Record<string, string>;
      }
  >(),
  enabled: boolean("enabled").notNull().default(true),
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

/**
 * Per-user connections to integrations.
 * Stores OAuth credentials (JSON) for each user × service pair.
 */

export const userIntegration = pgTable(
  "user_integration",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    orgId: text("org_id").notNull(),
    userId: text("user_id")
      .notNull()
