export async function clearBrokerBackedIntegrationListCache(userId?: string): Promise<void> {
  if (userId) {
    await cache
      .deletePrefix(`${BROKER_INTEGRATION_LIST_CACHE_PREFIX}${userId}:`)
      .catch(() => undefined);
    return;
  }
  await cache.deletePrefix(BROKER_INTEGRATION_LIST_CACHE_PREFIX).catch(() => undefined);
}

export async function invalidateBrokerBackedIntegrationListCache(userId: string): Promise<void> {
  await clearBrokerBackedIntegrationListCache(userId);
}

