      options?.logger?.warn(
        "[integration-connected-state] API-key provider state unavailable:",
        apiKeyError,
      );
    }
    const result: BrokerBackedIntegrationListResult = { status: "ok", integrations };
    await cache.set(
      cacheKey,
      JSON.stringify({
        expiresAt: now + BROKER_INTEGRATION_LIST_TTL_MS,
