        orgId: options?.orgId,
      });
    } catch (apiKeyError) {
      options?.logger?.warn(
        "[integration-connected-state] API-key provider state unavailable:",
        apiKeyError,
      );
    }
    return {
      status: localBrokerDisabled ? "ok" : "degraded",
      integrations,
    };
  }
}

