export interface IntegrationRuntimeLogger {
  warn: (...args: unknown[]) => void;
  debug?: (...args: unknown[]) => void;
}

/** Log broker gaps once at info in local-dev when AUTH_ADMIN_SECRET is unset. */
let localBrokerGapLogged = false;

function logBrokerRegistryUnavailable(
  logger: IntegrationRuntimeLogger | undefined,
  prefix: string,
  err: unknown,
): void {
  const message = err instanceof Error ? err.message : String(err);
  if (isLocalDevWithoutAuthAdminSecret()) {
    if (!localBrokerGapLogged) {
      localBrokerGapLogged = true;
      logger?.warn(
        `${prefix} local-dev without AUTH_ADMIN_SECRET — cloud integration OAuth disabled (expected)`,
      );
    } else {
      logger?.debug?.(prefix, message);
    }
    return;
  }
  logger?.warn(prefix, err);
}

export interface IntegrationBrokerConnectedState {
  connectedSlugs: ReadonlySet<string>;
  integrations: readonly GenesisOAuthIntegration[] | null;
  brokerUnavailable: boolean;
}

export type BrokerBackedIntegrationListStatus = "ok" | "degraded";

export interface BrokerBackedIntegrationListResult {
  status: BrokerBackedIntegrationListStatus;
  integrations: IntegrationListItem[];
}

const BROKER_INTEGRATION_LIST_TTL_MS = Number(
  process.env.GENESIS_BROKER_INTEGRATION_LIST_CACHE_MS ?? 45_000,
);
const BROKER_INTEGRATION_LIST_STALE_TTL_SECONDS = Math.max(
  300,
  Math.ceil(BROKER_INTEGRATION_LIST_TTL_MS / 1000) * 2,
);
const BROKER_INTEGRATION_LIST_CACHE_PREFIX = "integration-broker-list:v1:";

interface CachedBrokerBackedIntegrationList {
  expiresAt: number;
  result: BrokerBackedIntegrationListResult;
}

function brokerBackedIntegrationListCacheKey(userId: string, orgId?: string | null): string {
  const org = tryResolveTenantOrgIdForWrite(orgId) ?? "";
  return `${BROKER_INTEGRATION_LIST_CACHE_PREFIX}${userId}:${org}`;
}

async function readBrokerBackedIntegrationListCache(
  key: string,
): Promise<CachedBrokerBackedIntegrationList | null> {
  const raw = await cache.get(key).catch(() => null);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as CachedBrokerBackedIntegrationList;
  } catch {
    await cache.delete(key).catch(() => undefined);
    return null;
  }
}

async function mergePrintavoListItem(
  integrations: readonly IntegrationListItem[],
  userId: string,
  orgId: string | null | undefined,
  logger?: IntegrationRuntimeLogger,
): Promise<IntegrationListItem[]> {
  const tenantOrgId = tryResolveTenantOrgIdForWrite(orgId);
  if (!tenantOrgId) return [...integrations];
  try {
    const printavoRow = await buildPrintavoApiKeyListItem(userId, tenantOrgId);
    return [
      ...integrations.filter((item) => item.id !== PRINTAVO_INTEGRATION_ID),
      printavoRow,
    ].sort((left, right) => left.name.localeCompare(right.name));
  } catch (error) {
    logger?.warn("[integration-connected-state] Printavo connected state unavailable:", error);
    return [...integrations];
  }
}


