import type { IntegrationConnectionSummary } from "../domain/integration";
import type { IntegrationPostConnectGuidance } from "../domain/integration-post-connect";
import { resolveIntegrationPostConnectGuidance } from "../domain/integration-post-connect";
import { getIntegrationSyncModule } from "../integrations/sync/registry";
import type { GenesisOAuthIntegration } from "../lib/genesis-oauth";
import type { GenesisOAuthCredentialStrategy } from "../lib/oauth-provider-registry";
import { isDcrOAuthProvider, registryProviderLogo } from "../lib/oauth-provider-registry";
import { resolveIntegrationSyncCapable } from "./integration-sync/sync-capability";

/** Broker OAuth strategies, plus Genesis-local API-key providers (e.g. Shopmonkey). */
export type IntegrationDevSource = GenesisOAuthCredentialStrategy | "custom";

export interface IntegrationListItem extends IntegrationConnectionSummary {
  devSource?: IntegrationDevSource;
  logo?: string | null;
  postConnect?: IntegrationPostConnectGuidance | null;
  /** False when Collections sync module exists but broker sync OAuth is not registered yet. */
  syncCapable?: boolean;
  /** True only when the sync module actually auto-starts entities on connect. */
  autoSyncOnConnect?: boolean;
}

/** True when the integration's sync module auto-enables entities right after connect. */
export function resolveAutoSyncOnConnect(integrationId: string): boolean {
  const module = getIntegrationSyncModule(integrationId);
  return Boolean(module?.autoEnableOnConnect?.length);
}

export function isRegistryOAuthProvider(
  integrationId: string,
  registryProviders: readonly GenesisOAuthIntegration[],
): boolean {
  const normalized = integrationId.trim().toLowerCase();
  return registryProviders.some((item) => item.slug === normalized);
}

/** @deprecated Use isRegistryOAuthProvider — all Ion registry providers use the broker OAuth path. */
export function isBrokeredOAuthIntegration(
  integrationId: string,
  registrySlugs?: ReadonlySet<string>,
): boolean {
  return registrySlugs?.has(integrationId.trim().toLowerCase()) ?? false;
}

export function isDcrOAuthIntegration(
  provider: Pick<GenesisOAuthIntegration, "credential_strategy">,
): boolean {
  return isDcrOAuthProvider(provider);
}

export function buildIntegrationListFromRegistry(
  oauthIntegrations: GenesisOAuthIntegration[],
): IntegrationListItem[] {
  return oauthIntegrations
    .map((provider) => {
      const postConnect = resolveIntegrationPostConnectGuidance({
        slug: provider.slug,
        runtimeConfig: provider.runtime_config,
      });
      return {
        id: provider.slug,
        name: provider.name,
        description: provider.description ?? null,
        connected: provider.connected,
        displayName: provider.display_name ?? null,
        connectedAt: provider.connected_at ?? null,
        devSource: provider.credential_strategy,
        logo: registryProviderLogo(provider.logo),
        syncCapable: resolveIntegrationSyncCapable(provider.slug, provider),
        autoSyncOnConnect: resolveAutoSyncOnConnect(provider.slug),
        ...(postConnect ? { postConnect } : {}),
      };
    })
    .sort((left, right) => left.name.localeCompare(right.name));
}

export function registryIntegrationSummaries(
  oauthIntegrations: GenesisOAuthIntegration[],
): IntegrationConnectionSummary[] {
  return buildIntegrationListFromRegistry(oauthIntegrations).map(
    ({ id, name, description, connected, displayName, connectedAt }) => ({
      id,
      name,
      description,
      connected,
      displayName,
      connectedAt,
    }),
  );
}

