import { Hono } from "hono";
import { beforeEach, describe, expect, test, vi } from "vitest";
import { z } from "zod";
import type { Logger } from "../../lib/logger";
import type { Env } from "../../types/hono-env";

const lifecycleSchema = z.enum(["experimental", "production", "disabled"]);

const patchOpsOAuthServiceSchema = z
  .object({
    name: z.string().trim().min(1).max(200).optional(),
    description: z.string().trim().max(280).optional(),
    category: z.string().trim().min(1).max(64).optional(),
    logo: z.string().trim().max(500_000).nullable().optional(),
  })
  .strict();

const patchOpsOAuthConnectionSchema = z
  .object({
    lifecycleStatus: lifecycleSchema.optional(),
    handlerKind: z.string().trim().min(1).max(64).optional(),
    clientId: z.string().trim().max(500).optional(),
    clientSecret: z.string().max(2000).optional(),
    authUrl: z.string().trim().url().max(2000).optional(),
    tokenUrl: z.string().trim().url().max(2000).optional(),
    userInfoUrl: z.string().trim().url().max(2000).nullable().optional(),
    defaultScopes: z.array(z.string().trim().min(1).max(200)).max(200).optional(),
    defaultUserScopes: z.array(z.string().trim().min(1).max(200)).max(200).optional(),
    allowedScopes: z.array(z.string().trim().min(1).max(200)).max(500).optional(),
    scopeDelimiter: z.string().max(8).optional(),
    scopeParam: z.string().trim().min(1).max(64).optional(),
    tokenAccessPath: z.string().trim().max(200).nullable().optional(),
    pkce: z.boolean().optional(),
    publicClient: z.boolean().optional(),
    extraAuthParams: z.record(z.string(), z.string()).optional(),
    experimentalOrgIds: z.array(z.string().trim().min(1).max(128)).max(500).optional(),
    dcrRegistrationUrl: z.string().trim().url().max(2000).nullable().optional(),
    dcrClientName: z.string().trim().max(200).nullable().optional(),
    dcrLogoUri: z.string().trim().max(2000).nullable().optional(),
    dcrExtraRegistrationParams: z.record(z.string(), z.unknown()).optional(),
    runtimeConfig: z.unknown().optional(),
  })
  .strict();

const { listOpsOAuthRegistry, getOpsOAuthService, patchOpsOAuthConnection, patchOpsOAuthService } =
  vi.hoisted(() => ({
    listOpsOAuthRegistry: vi.fn(async () => [
      {
        service: "xero",
        name: "Xero",
        description: "Accounting",
        category: "finance",
        logo: null,
        connections: [
          {
            credentialStrategy: "static" as const,
            lifecycleStatus: "experimental" as const,
            handlerKind: "xero",
            experimentalOrgCount: 1,
            clientSecretConfigured: true,
          },
        ],
      },
    ]),
    getOpsOAuthService: vi.fn(async (service: string) =>
      service === "xero"
        ? {
            service: "xero",
            name: "Xero",
            description: "Accounting",
            category: "finance",
            logo: null,
            connections: [],
          }
        : null,
    ),
    patchOpsOAuthConnection: vi.fn(
      async (_service: string, _strategy: string, input: { lifecycleStatus?: string }) => ({
        service: "xero",
        credentialStrategy: "static" as const,
        lifecycleStatus: (input.lifecycleStatus ?? "experimental") as
          | "experimental"
          | "production"
          | "disabled",
        handlerKind: "xero",
        clientId: "cid",
        clientSecretConfigured: true,
        authUrl: "https://example.com/auth",
        tokenUrl: "https://example.com/token",
        userInfoUrl: null,
        defaultScopes: ["openid"],
        defaultUserScopes: [],
        allowedScopes: ["openid"],
        scopeDelimiter: " ",
        scopeParam: "scope",
        tokenAccessPath: null,
        pkce: false,
        publicClient: false,
        extraAuthParams: {},
        experimentalOrgIds: ["org_1"],
        dcrRegistrationUrl: null,
        dcrClientName: null,
        dcrLogoUri: null,
        dcrExtraRegistrationParams: {},
        dcrRegisteredAt: null,
        runtimeConfig: {},
        version: 2,
        disabledAt: null,
      }),
    ),
    patchOpsOAuthService: vi.fn(async () => ({
      service: "xero",
      name: "Xero Updated",
      description: "Accounting",
      category: "finance",
      logo: null,
      connections: [],
    })),
  }));

vi.mock("../../services/ops/oauth-registry", () => ({
  listOpsOAuthRegistry,
  getOpsOAuthService,
  patchOpsOAuthConnection,
  patchOpsOAuthService,
  patchOpsOAuthConnectionSchema,
  patchOpsOAuthServiceSchema,
  opsOAuthAdminErrorMessage: (error: unknown, fallback: string) =>
    error instanceof Error ? error.message : fallback,
  opsOAuthAdminErrorStatus: () => 502,
}));

vi.mock("../../lib/local-ops-bootstrap", () => ({
  isLocalOpsBootstrapEnabled: () => false,
}));

let authEmail = "grodrigues@agentuity.com";

async function createApp() {
  const opsRoutes = (await import("./ops")).default;
  const app = new Hono<Env>();
  app.use("*", async (c, next) => {
    c.set("auth", {
      getUser: async () => ({
        id: "guser_ops",
        email: authEmail,
        name: "Ops",
        image: null,
        preferences: {},
      }),
    } as never);
    c.set("logger", {
      info: () => undefined,
      warn: () => undefined,
      error: () => undefined,
      debug: () => undefined,
    } as unknown as Logger);
    await next();
  });
  return app.route("/", opsRoutes);
}

describe("ops oauth registry routes", () => {
  beforeEach(() => {
    authEmail = "grodrigues@agentuity.com";
    listOpsOAuthRegistry.mockClear();
    getOpsOAuthService.mockClear();
    patchOpsOAuthConnection.mockClear();
    patchOpsOAuthService.mockClear();
  });

  test("lists registry for @agentuity.com ops users", async () => {
    const app = await createApp();
    const res = await app.request("/ops/integrations");
    expect(res.status).toBe(200);
    const body = (await res.json()) as { services: Array<{ service: string }> };
    expect(body.services[0]?.service).toBe("xero");
    expect(listOpsOAuthRegistry).toHaveBeenCalled();
  });

  test("forbids non-employee users", async () => {
    authEmail = "outsider@example.com";
    const app = await createApp();
    const res = await app.request("/ops/integrations");
    expect(res.status).toBe(403);
  });

  test("soft-disables a connection via PATCH", async () => {
    const app = await createApp();
    const res = await app.request("/ops/integrations/xero/connections/static", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ lifecycleStatus: "disabled" }),
    });
    expect(res.status).toBe(200);
    const body = (await res.json()) as {
      connection: { lifecycleStatus: string; clientSecretConfigured: boolean };
    };
    expect(body.connection.lifecycleStatus).toBe("disabled");
    expect(body.connection.clientSecretConfigured).toBe(true);
    expect(JSON.stringify(body)).not.toContain("client_secret");
    expect(patchOpsOAuthConnection).toHaveBeenCalledWith("xero", "static", {
      lifecycleStatus: "disabled",
    });
  });

  test("rejects invalid connection patches", async () => {
    const app = await createApp();
    const res = await app.request("/ops/integrations/xero/connections/static", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ lifecycleStatus: "live", unexpected: true }),
    });
    expect(res.status).toBe(400);
  });
});

