export async function loadUserOwnedConnectionProviderInstance(
  scope: AppCapabilityGatewayStoreOptions,
  capabilityId: string,
): Promise<CapabilityRecord | undefined> {
  const logicalId = logicalStorageId(scope, capabilityId);
  const [row] = await scope.db
    .select()
    .from(capabilityRecord)
    .where(
      and(
        eq(capabilityRecord.userId, scope.userId),
        eq(capabilityRecord.scopeKey, scopeKeyFor(scope)),
        eq(capabilityRecord.capabilityId, logicalId),
      ),
    )
    .limit(1);
  if (!row) return undefined;
  const stored = row.record as CapabilityRecord;
  return { ...stored, id: row.capabilityId };
}

