const { listOpsIntegrationsForOrg, listOpsOrgsForIntegration } = await import("./ops-directory");

const older = new Date("2026-08-11T12:00:00.000Z");
const newer = new Date("2026-08-11T13:00:00.000Z");

describe("Ops integration directory", () => {
  beforeEach(() => {
    selectResults = [];
  });

  test("includes broker-backed connection capabilities for an organization", async () => {
    selectResults = [
      [
        {
          integrationId: "linear",
          name: "Linear",
          description: "Issue tracking",
          userId: "user_1",
          connectedAt: older,
        },
      ],
      [{ userId: "user_1" }],
      [
        {
          capabilityId: "connection:linear",
          name: "Linear",
          userId: "user_1",
          scopeKey: "user:user_1:org:org_1",
          connectedAt: newer,
        },
      ],
