import {
  SettingsTabControls,
  SettingsTabCount,
  settingsTabSelectTriggerClass,
} from "@web/components/settings/settings-section";
import { Search } from "lucide-react";
import { useMemo, useState } from "react";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { isYoursConnector } from "./build-connectors-catalog";
import { CatalogBrowseTable } from "./catalog-browse-table";
import { CONNECTOR_CATEGORIES } from "./categories";
import type {
  ConnectorCardActionHandlers,
  ConnectorCategoryId,
  ConnectorRecord,
  ConnectorSource,
} from "./types";

function sectionLabel(title: string, count: number) {
  return (
    <div className="flex items-center gap-2">
      <h3 className="text-sm font-medium text-foreground">{title}</h3>
      <SettingsTabCount count={count} />
    </div>
  );
}

function matchesSource(connector: ConnectorRecord, source: ConnectorSource | "all"): boolean {
  if (source === "all") return true;
  if (source === "genesis") return connector.source === "genesis" || connector.source === "both";
  if (source === "mcp") return connector.source === "mcp" || connector.source === "both";
  return connector.source === source;
}

export function CatalogLayoutA({
  connectors,
  focusedId,
  actions,
  /** Marketplace size: integrations.sh MCP total + available Genesis natives. */
  browseTotal,
  catalogReady,
  hasMore,
  loadingMore,
  onLoadMore,
  searchQuery,
  onSearchChange,
}: {
  connectors: ConnectorRecord[];
  focusedId?: string | null;
  actions: ConnectorCardActionHandlers;
  browseTotal: number;
  catalogReady: boolean;
  hasMore: boolean;
  loadingMore: boolean;
  onLoadMore: () => void;
  searchQuery: string;
  onSearchChange: (query: string) => void;
}) {
  const [category, setCategory] = useState<ConnectorCategoryId | "all">("all");
  const [source, setSource] = useState<ConnectorSource | "all">("all");

  const yours = connectors.filter((c) => isYoursConnector(c.status));

  const browse = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    return (
      connectors
        .filter((c) => !isYoursConnector(c.status))
        // Natives are not server-searched; filter them (and any residual rows) locally.
        .filter((c) => {
          if (!q) return true;
          if (c.kind === "catalog_mcp") return true; // already matched by API
          const hay = `${c.name} ${c.description} ${c.id}`.toLowerCase();
          return hay.includes(q);
        })
        .filter((c) => category === "all" || c.category === category)
        .filter((c) => matchesSource(c, source))
        .slice()
        .sort((a, b) => {
          if (b.popularity !== a.popularity) return b.popularity - a.popularity;
          return a.name.localeCompare(b.name);
        })
    );
  }, [category, connectors, searchQuery, source]);

  // Unfiltered: full marketplace size (API total). Search / category / source: rows on screen
  // after de-dupe and "already installed" suppress — never raw catalogMatchTotal alone.
  const listNarrowed = searchQuery.trim().length > 0 || category !== "all" || source !== "all";
  const browseBadgeCount = listNarrowed
    ? browse.length
    : catalogReady && browseTotal > 0
      ? browseTotal
      : Math.max(browse.length, browseTotal);

  return (
    <div className="flex flex-col gap-6 md:min-h-0 md:flex-1">
      <div className="flex flex-col gap-2">
        {sectionLabel("Your connectors", yours.length)}
        <CatalogBrowseTable
          variant="yours"
          items={yours}
          focusedId={focusedId}
          actions={actions}
          emptyMessage="None connected yet."
        />
      </div>

      <div className="flex flex-col gap-3 md:min-h-0 md:flex-1">
        {sectionLabel("Browse", browseBadgeCount)}

        {/* Toolbar sits on the table (Activity pattern): search left, filters right. */}
        <div className="flex w-full flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="relative min-w-0 w-full sm:max-w-sm">
            <Search
              className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground"
              aria-hidden="true"
            />
            <Input
              value={searchQuery}
              onChange={(e) => onSearchChange(e.target.value)}
              placeholder="Search connectors"
              className="pl-8"
              aria-label="Search connectors"
            />
          </div>
          <SettingsTabControls className="w-full shrink-0 sm:ml-auto sm:w-auto sm:justify-end">
            <Select
              value={category}
              onValueChange={(value) => setCategory(value as ConnectorCategoryId | "all")}
            >
              <SelectTrigger
                className={settingsTabSelectTriggerClass}
                aria-label="Filter by category"
              >
                <SelectValue placeholder="All categories" />
              </SelectTrigger>
              <SelectContent align="end">
                <SelectItem value="all">All categories</SelectItem>
                {CONNECTOR_CATEGORIES.map((cat) => (
                  <SelectItem key={cat.id} value={cat.id}>
                    {cat.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Select
              value={source}
              onValueChange={(value) => setSource(value as ConnectorSource | "all")}
            >
              <SelectTrigger
                className={settingsTabSelectTriggerClass}
                aria-label="Filter by source"
              >
                <SelectValue placeholder="All sources" />
              </SelectTrigger>
              <SelectContent align="end">
                <SelectItem value="all">All sources</SelectItem>
                <SelectItem value="genesis">Genesis</SelectItem>
                <SelectItem value="mcp">MCP</SelectItem>
              </SelectContent>
            </Select>
          </SettingsTabControls>
        </div>

        <CatalogBrowseTable
          items={browse}
          focusedId={focusedId}
          actions={actions}
          hasMore={hasMore && !listNarrowed}
          loadingMore={loadingMore}
          onLoadMore={onLoadMore}
        />
      </div>
    </div>
  );
}

