/**
 * Jobber integration module.
 *
 * Fetches CRM, request, quote, job, visit, and invoice context for Genesis briefings.
 */

import { getJobberBriefingData } from "../lib/jobber";
import type { BriefingContext, IntegrationModule } from "./types";

function addKind<T extends object>(kind: string, item: T): T & { kind: string } {
  return { kind, ...item };
}

export const jobberIntegration: IntegrationModule = {
  id: "jobber",

  async getBriefingContext(accessToken: string): Promise<BriefingContext | null> {
    try {
      const data = await getJobberBriefingData(accessToken, 10);
      const context: Record<string, unknown> = {};

      if (data.account) context.account = data.account;
      if (data.upcomingVisits.length > 0) {
        context.upcomingVisits = data.upcomingVisits.map((visit) => addKind("visit", visit));
      }
      if (data.requests.length > 0) {
        context.requests = data.requests.map((request) => addKind("request", request));
      }
      if (data.quotes.length > 0) {
        context.quotes = data.quotes.map((quote) => addKind("quote", quote));
      }
      if (data.invoices.length > 0) {
        context.invoices = data.invoices.map((invoice) => addKind("invoice", invoice));
      }
      if (data.jobs.length > 0) {
        context.jobs = data.jobs.map((job) => addKind("job", job));
      }
      if (data.clients.length > 0) {
        context.clients = data.clients.slice(0, 5).map((client) => addKind("client", client));
      }

      if (Object.keys(context).length === 0) return null;

      return {
        label: "JOBBER",
        context: JSON.stringify(context),
        actionTypes: ["jobber_item"],
        instructions: `For jobber_item actions: refId should be the item "id" field and context.kind should identify visit, request, quote, invoice, job, or client. Suggest actions for upcoming visits needing preparation, new or stale requests, open quotes, invoices needing payment follow-up, and active jobs with missing follow-up. Do not suggest actions for completed visits or routine records with no clear next step.`,
      };
    } catch (err) {
      console.warn("[jobber] Failed to fetch data:", err);
      return null;
    }
  },
};

