import { renderToStaticMarkup } from "react-dom/server";
import { describe, expect, test, vi } from "vitest";
import { CatalogBrowseTable } from "./catalog-browse-table";
import type { ConnectorCardActionHandlers, ConnectorRecord } from "./types";

const connector: ConnectorRecord = {
  id: "catalog:example.com",
  name: "Example",
  description: "Example connector",
  iconUrl: null,
  category: "other",
  source: "mcp",
  status: "available",
  badges: ["MCP"],
  installedDetail: null,
  kind: "catalog_mcp",
  integrationId: null,
  userMcpServerId: null,
  catalogDomain: "example.com",
  connectedDisplayName: null,
  syncCapable: false,
  popularity: 1,
};

const actions: ConnectorCardActionHandlers = {
  userMcpServers: [],
  onConnect: vi.fn(),
  onReconnect: vi.fn(),
  onNativeDisconnected: vi.fn(),
  onUserMcpChanged: vi.fn(),
};

describe("CatalogBrowseTable", () => {
  test("fills the available desktop height and keeps its own scrollport", () => {
    const html = renderToStaticMarkup(
      <CatalogBrowseTable items={[connector]} actions={actions} hasMore />,
    );

    expect(html).toContain("data-connectors-scrollport");
    expect(html).toContain("md:max-h-none");
    expect(html).toContain("md:min-h-0");
    expect(html).toContain("md:flex-1");
  });
});

